data: {"index":1,"delta":{"text":" overall energy demand.\n*   **Reforestation:** Planting billions of trees and protecting existing old-growth forests to","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" sequester carbon.\n\n**Adaptation** acknowledges that some warming is already \"baked in\" and requires resilience:\n*","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"   **Infrastructure:** Building sea walls, improving drainage systems, and designing \"sponge cities\" to manage flooding.\n*","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"   **Agriculture:** Developing drought-resistant crop varieties and implementing sustainable irrigation techniques.\n\nOn a global scale, the **","type":"text"},"event_type":"step.delta"}

